// Execute only the fixed TS pure FCM payload builder; no Firebase or network.
import {readFile,writeFile} from 'node:fs/promises';import {createHash} from 'node:crypto';import {pathToFileURL} from 'node:url';import assert from 'node:assert/strict';
const evidence=JSON.parse(await readFile(process.env.TS_SERVER_EVIDENCE,'utf8'));const source=evidence.files['infra/message-box-server/src/utils/sendFCMNotification.ts'].content,bytes=Buffer.from(source),sha=createHash('sha1').update(`blob ${bytes.length}\0`).update(bytes).digest('hex');assert.equal(sha,'277933451708a86fa23b975e26c33490c5ae1306');
const first=source.indexOf('export function buildFCMMessage('),last=source.indexOf('\n}\n',first)+2;assert.ok(first>0&&last>first);const constant=source.match(/^const GENERIC_NOTIFICATION_BODY = .*$/m)?.[0];assert.ok(constant);const piece=`${constant}\n${source.slice(first,last).replace('export function','function')}\nreturn buildFCMMessage;`;
const ts=(await import(pathToFileURL(process.env.TYPESCRIPT_LIB).href)).default,js=ts.transpileModule(piece,{compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.None}}).outputText,build=new Function(js)();
const inputs=[{token:'fake-token',title:'New Message',messageId:'id-1'},{token:'fake-token',title:'',messageId:'id-2',originator:''},{token:'another-fake-token',title:'提示',messageId:'猫',originator:'origin.test'},{token:'fake',title:'Title',messageId:'id-3',originator:null}];const cases=inputs.map(input=>({input,output:build(input.token,{title:input.title,messageId:input.messageId,...('originator' in input?{originator:input.originator}:{})})}));await writeFile(process.argv[2],JSON.stringify({sourceBlob:sha,cases},null,2)+'\n');console.log(`Generated ${cases.length} pure FCM payload observations, no provider or network.`);
